function editMember(mid){if(!chief())return;let m=person(mid);modal(m?'编辑成员':'新增成员',field('姓名','name',m?.name,'text','required')+`<label>部门<select name="dept">${options(departments,m?.dept)}</select></label><label>在册状态<select name="active">${options([['yes','在册'],['no','停用']],m?.active===false?'no':'yes')}</select></label>`,f=>{if(m&&m.dept!==f.get('dept')&&db.subs.some(s=>s.contrib.some(c=>c.member===mid))){alert('已有贡献记录的成员暂不支持转部门，避免改写历史归属');return false}let v={name:f.get('name').trim(),dept:f.get('dept'),active:f.get('active')==='yes'};if(m)Object.assign(m,v);else db.members.push({id:id(),...v});commit('维护成员：'+v.name)})}function download(text,name,type='application/json'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function exportReport(){let rows=[['姓名','部门','原始积分','适用目标','自由项得分','固定项得分','综合分','状态'],...results().filter(filter).map(m=>[m.name,m.dept,m.p,m.t,m.v?.toFixed(2)??'',m.fixed?.toFixed(2)??'',m.total?.toFixed(2)??'',m.status])];download('\ufeff'+rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n'),month()+'绩效.csv','text/csv;charset=utf-8')}function copyReport(){modal('转发核对稿',`<textarea style="width:100%;height:320px">${E(month()+' 绩效核对稿\n'+results().filter(filter).map(m=>`${m.dept} ${m.name}：自由项${m.p}积分，综合${m.total?.toFixed(2)??m.status}${m.opportunity?'（机会不足）':''}`).join('\n')+'\n公示3天，异议原则上5个工作日内复核；最终以上级审核为准。')}</textarea>`,()=>{})}function backup(){if(!chief())return;download(JSON.stringify(db,null,2),'粤港联绩效备份-'+month()+'.json')}
function assignDepartments(oid){if(!chief())return;let o=db.operators.find(x=>x.id===oid);modal('分配负责部门：'+o.name,departments.map(d=>`<label><input style="width:auto" name="departments" type="checkbox" value="${d}" ${o.departments?.includes(d)?'checked':''}>${d}</label>`).join(''),f=>{o.departments=f.getAll('departments');commit('分配负责部门：'+o.name)})}
if(!db.departmentScopeVersion){db.operators.forEach(o=>{o.departments=o.id==='staff1'?['宣传部','公关部']:o.id==='staff2'?['策划部','会务部','内务部']:departments});db.subs.forEach(s=>{if(s.status==='待审核')s.status='已通过'});db.departmentScopeVersion=1;localStorage.setItem('ygl-v2',JSON.stringify(db))}
$('#month').onchange=()=>{projectId=null;taskId=null;render()};render();

